export function lookupFeatureTranslation(language, english) {
  const locale = typeof language === 'string' ? language.toLowerCase().split(/[-_]/, 1)[0] : '';
  if (!Object.hasOwn(languageIndex, locale) || !Object.hasOwn(labels, english)) return undefined;
  return labels[english][languageIndex[locale]];
}

export function featureText(language, polish, english) {
  const locale = typeof language === 'string' ? language.toLowerCase().split(/[-_]/, 1)[0] : '';
  if (locale === 'pl' || (locale !== 'en' && !Object.hasOwn(languageIndex, locale))) return polish;
  return lookupFeatureTranslation(locale, english) ?? english ?? polish;
}

