const allLanguageIndex = Object.freeze({pl: 0, en: 1, cs: 2, sk: 3, de: 4, uk: 5});

function labelByKey(table, key, language) {
  if (!Object.hasOwn(table, key)) return '';
  const code = typeof language === 'string' ? language.toLowerCase().split(/[-_]/, 1)[0] : '';
  return table[key][Object.hasOwn(allLanguageIndex, code) ? allLanguageIndex[code] : 0];
}

export const importFieldLabel = (key, language = 'pl') => labelByKey(importLabels, key, language);
export const importStatusLabel = (key, language = 'pl') => labelByKey(importStatuses, key, language);
